<div class="alan-izgara c2">${alan('tAd', 'Ad', girdi('tAd', 'text', ' required autocomplete="given-name"'), { zorunlu: 1 })}${alan('tSoyad', 'Soyad', girdi('tSoyad', 'text', ' required autocomplete="family-name"'), { zorunlu: 1 })}${alan('tMarka', 'Marka', girdi('tMarka', 'text', ' required autocomplete="organization" placeholder="Marka adı"'), { zorunlu: 1 })}${alan('tEposta', 'İş e-postası', girdi('tEposta', 'email', ' required autocomplete="email" placeholder="ad@markaniz.com"'), { zorunlu: 1, hata: 'Geçerli bir e-posta yaz.' })}</div>
