const yasal = () => sayfa('yasal', 'Yasal Metinler',
  bant({ yol: [['Yasal Metinler']], etiket: 'DADA DİET', etiketIkon: 'fa-scale-balanced', h1: 'Yasal Metinler', alt: 'Her metnin başında yürürlük sürümü ve son güncelleme tarihi bulunur.' })
  + dizi(bolum(`<div class="yigin">${okuma('<p class="okuma-giris">Dada Diet\'i kullanırken geçerli olan sözleşmeler, sağlık içeriği ve tıbbi sorumluluk metinleri ile sağlık verisi ve gizlilik politikaları burada toplanır. Metinler dört başlık altında gruplanmıştır.</p>')}${YASAL_GRUP.map(([g, l]) => `<div class="yigin sik"><h2 class="kart-baslik">${g}</h2>${izgara(l.map(([a, h, i]) => ikonKart({ href: h, ikon: i, baslik: a, metin: 'Metni oku' })).join(''), 'c2')}</div>`).join('')}<p class="sonuc-not-kisa">${YASAL_NOT}</p></div>`, { ilk: true })));

/* Canlıdaki belge menüsünün sırası */
const YASAL_BELGE = [['kullanim-kosullari', 'Kullanım Koşulları'], ['tibbi-sorumluluk-reddi', 'Tıbbi Sorumluluk Reddi'], ['saglik-verisi', 'Sağlık Verisi Politikası'], ['gizlilik', 'Gizlilik Politikası'], ['kvkk', 'KVKK Aydınlatma Metni'], ['cerez', 'Çerez Politikası'], ['diyetisyen-dogrulama', 'Diyetisyen Doğrulama ve Kabul Politikası']];
const BELGE_MENU = [...YASAL_BELGE.map(([y, a]) => [a, `yasal/${y}/`]), ['Künye', 'sayfa/kunye/'], ['Bilimsel Kaynaklar', 'sayfa/bilimsel-kaynaklar/'], ['Tüm Yasal Metinler', 'yasal/']];

function yasalBelge({ yol, baslik, anahtar, tarih, kirinti }) {
  const b = metin.yasal[anahtar].bloklar;
  const taslak = b[0].h.startsWith('<strong>Durum:') ? b[0] : null;
  const govde = taslak ? b.slice(1) : b;
  const icindekiler = govde.filter((x) => x.t === 'h2' || x.t === 'h3').map((x) => `<li${x.t === 'h3' ? ' class="alt-kalem"' : ''}><a href="#${x.id}">${x.h}</a></li>`).join('');
  const menu = BELGE_MENU.map(([a, h]) => `<li><a href="${K}${h}"${h === `${yol}/` ? ' aria-current="page"' : ''}>${a}</a></li>`).join('');
  return sayfa(yol, baslik,
    bant({ yol: kirinti, etiket: 'YASAL METİNLER', etiketIkon: 'fa-scale-balanced', h1: baslik, alt: `Sürüm: 1.0 · ${tarih}` })
    + dizi(bolum(`<div class="iki-kolon sol-yan"><aside class="yigin yapiskan" aria-label="Belge gezintisi">
<div class="kart"><div class="kart-bas"><h2 class="kart-baslik">${ikon('fa-list')} İçindekiler</h2></div><div class="kart-govde"><ul class="baglanti-liste">${icindekiler}</ul></div></div>
<div class="kart"><div class="kart-bas"><h2 class="kart-baslik">${ikon('fa-scale-balanced')} Yasal Metinler</h2></div><div class="kart-govde"><ul class="baglanti-liste">${menu}</ul></div></div></aside>
<div class="yigin">${taslak ? uyari(taslak.h) : ''}<article class="okuma">${bloklar(govde)}</article><p class="sonuc-not-kisa">Bu metin bilgilendirme amaçlıdır; güncel sürüm her zaman bu sayfada yayımlanır.</p></div></div>`, { ilk: true })));
}

/* Kurumsal */
function hakkimizda(veri) {
  const s = veri.sayaclar;
  const araclar = [['Hesaplayıcılar', 'Kalori, makro, su ve vücut ölçüleri', 'hesaplayicilar/', 'fa-calculator'], ['Beslenme Testleri', 'Alışkanlıklarını ölçen kısa testler', 'saglik-testleri/', 'fa-clipboard-question'], ['Beslenme Programları', 'Hedefe göre kurulmuş haftalık menüler', 'programlar/', 'fa-list-check'], ['Besin Kütüphanesi', '100 gram referanslı besin değerleri', 'besin-kutuphanesi/', 'fa-magnifying-glass'], ['Diyetisyenler', 'Diyetisyenlerle iletişim ve randevu', 'diyetisyenler/', 'fa-user-doctor'], ['Dışarıda Ne Yesem', 'Şehrindeki mekanlarda hedefine uygun öğünler', 'disarida-ne-yesem/', 'fa-location-dot']];
  const alanlar = [['Yazılar ve Rehberler', 'Beslenmeyle ilgili günlük soruları yanıtlayan rehber, ipucu ve püf noktası içerikleri.', 'Beslenmeye git', 'besin-rehberi/'], ['Hesaplayıcılar', 'Kalori, makro, su ve vücut ölçüleri. Her araç hangi denklemi kullandığını kendi sayfasında yazar.', 'Hesaplayıcılara git', 'hesaplayicilar/'], ['Besin Kütüphanesi', '100 gram referanslı besin değerleri; her kayıt kaynağını ve erişim tarihini künyesinde taşır.', 'Kütüphaneye git', 'besin-kutuphanesi/'], ['Beslenme Programları', 'Hedefe göre kurulmuş haftalık programlar, alışveriş listesi ve günlük takip.', 'Programlara git', 'programlar/'], ['Diyetisyen Dizini', 'Diyetisyenlerle iletişim ve randevu. Kişiye özel değerlendirme yalnız burada yapılır.', 'Dizine git', 'diyetisyenler/'], ['Diyetisyen Ol', 'Diploman ve mesleki kaydın kontrol edilir; doğrulama rozeti otomatik verilmez. Başvuru sürecini buradan başlatabilirsin.', 'Başvuruyu aç', 'diyetisyen-ol/']];
  return sayfa('sayfa/hakkimizda', 'Hakkımızda',
    bant({ yol: [['Hakkımızda']], etiket: 'HİKÂYEMİZ', etiketIkon: 'fa-seedling', h1: 'Hakkımızda', alt: 'Dada Diet nedir, neyi amaçlar.', gorsel: GORSEL.hakkimizda, sayilar: [[s.icerik_toplam, 'yayında yazı'], [s.besin, 'besin değeri'], [s.test, 'beslenme testi']] })
    + dizi(
      bolum(`${bolumBas({ etiket: 'NEDEN BURADAYIZ', ikon: 'fa-compass', baslik: 'Sayıyı Yazmak Kolay, Nereden Geldiğini Yazmak Zor', metin: 'Amacımız, güvenilir kaynaklara dayanan beslenme bilgisini karmaşık tıbbi dilden arındırıp herkesin gündelik hayatında kullanabileceği, anlaşılır bir biçimde sunmaktır.' })}
<div class="iki-kolon"><article class="okuma"><h2>Dada Diet ne yapar?</h2><p>Platformda dört ana alan bulunur: beslenmeyle ilgili günlük soruları yanıtlayan rehber ve ipucu içerikleri, kalori ve makro hesaplayıcıları, hedefe göre kurulmuş beslenme programları ve diyetisyenlerle buluşulan bir dizin. Bu alanların hepsi aynı editöryal disiplinle yönetilir: <b>hiçbiri tanı koymaz, hiçbiri tedaviyi değiştirmez</b>, hepsi genel bilgilendirme amacı taşır.</p><p>Bazı ziyaretçiler tek bir sayıyı (bir öğünün kalorisi gibi) merak ederken, bazıları haftalık bir program ya da bir diyetisyenle uzun soluklu bir çalışma arar; platform bu iki uçtaki ihtiyacı da aynı çatı altında karşılamak için kurulmuştur.</p>
<h2>İçerikler nasıl hazırlanır?</h2><p>Beslenmeyle ilgili her sayı (kalori değeri, porsiyon ağırlığı, referans alım miktarı) üç kaynaktan birine dayanır: TürKomp, TÜBER 2022 ve USDA FoodData Central. Bu kaynaklardan hangisinin kullanıldığı, ilgili besin ya da hesaplayıcı kaydının künyesinde ayrı ayrı görünür.</p><p><b>Kaynağı gösterilemeyen bir sayı yayınlanmaz.</b></p><p>Bu üç kaynağın ne işe yaradığını ve aralarındaki farkı <a href="{{kok}}sayfa/bilimsel-kaynaklar/">Bilimsel Kaynaklar</a> sayfasında ayrıntılı okuyabilirsin.</p><p>Yazı ve rehber içerikleri Dada Diet Beslenme Ekibi tarafından hazırlanır ve yayın öncesi bu içerik standardına göre gözden geçirilir. Künyenin neden kurumsal kaldığını da açıkça söylemek isteriz: bir içeriğin altına gerçek bir diyetisyenin adı ancak o kişi metni gerçekten okumuş, onaylamış ve bu onayın tarihi kayıt altına alınmışsa yazılır.</p><p>Bu üç şart birlikte sağlanmadığı sürece içerik Dada Diet Beslenme Ekibi imzasıyla kalır; amaç, var olmayan bir uzman onayını var gibi göstermemektir. Bugün itibarıyla bu sayfalar da dahil hiçbir içerik üçüncü şartı, yani kayıtlı, tarihli bir uzman onayını henüz karşılamıyor; bu yüzden hepsi kurumsal imzayla yayınlanır.</p></article>
<aside class="yigin yan-sabit"><div class="kart"><div class="kart-bas"><div><h2 class="kart-baslik">${ikon('fa-certificate')} ${s.besin} Besin Değerinin Tamamı Künyeli</h2><p>Kaynak, kayıt kimliği, porsiyon ve erişim tarihi: dördü birden yazılmayan bir değer yayınlanmaz.</p></div></div><div class="kart-govde"><dl class="kunye tek-sutun"><div><dt>Beslenme programı</dt><dd>${s.program}</dd></div><div><dt>Hesaplayıcı</dt><dd>${s.hesaplayici}</dd></div></dl></div></div></aside></div>`, { ilk: true }),
      bolum(`${bolumBas({ etiket: 'HANGİ ARAÇLARI BULURSUN', ikon: 'fa-toolbox', baslik: 'Hangi Araçları Bulursun?', metin: 'Bu araçların her biri kendi sayfasında nasıl çalıştığını ve hangi kaynağa dayandığını ayrıca açıklar; bir hesaplayıcının hangi denklemi kullandığı ya da bir testin sonuç bantlarının neye dayandığı, o aracın kendi sayfasında yazılıdır.' })}${izgara(araclar.map(([b, m, h, i]) => ikonKart({ href: h, ikon: i, baslik: b, metin: m })).join(''), 'c2')}`),
      bolum(`${bolumBas({ etiket: 'PUSULAMIZ', ikon: 'fa-compass', baslik: 'Neyi Yapıyoruz, Neyi Yapmıyoruz', metin: 'Bu üç cümle her içerik kararının arkasında duruyor.' })}${izgara([['fa-bullseye', 'Amacımız', 'Güvenilir kaynaklara dayanan beslenme bilgisini karmaşık tıbbi dilden arındırmak ve herkesin gündelik hayatında kullanabileceği anlaşılır bir biçimde sunmak.'], ['fa-shield-halved', 'Sınırımız', 'Hiçbir ekranda tanı konmaz, tedavi önerilmez, hastalık yönetimi tarif edilmez. Kişiye özel değerlendirmeyi yalnız doğrulanmış bir diyetisyen yapar.'], ['fa-signature', 'İmzamız', 'Bir içeriğin altına gerçek bir diyetisyenin adı ancak o kişi metni okumuş, onaylamış ve onayın tarihi kayda geçmişse yazılır. Üçü birden sağlanmadıkça içerik kurumsal imzayla kalır.']].map(([i, b, m]) => metinKart({ ikon: i, baslik: b, metin: m })).join(''))}`),
      bolum(`${bolumBas({ etiket: 'DAYANAĞIMIZ', ikon: 'fa-book-medical', baslik: 'Sayılar Nereden Geliyor?', metin: 'Beslenmeyle ilgili her sayı (kalori, porsiyon, referans alım) üç veri tabanından birine dayanır ve hangisinden geldiği kaydın künyesinde ayrıca görünür.' })}<div class="yigin">${izgara([['TürKomp', 'Ulusal Gıda Kompozisyon Veri Tabanı. Türkiye’de üretilen ve tüketilen gıdaların laboratuvarda analiz edilmiş bileşimi; yerel çeşit ve geleneksel ürünlerde birinci tercih.'], ['TÜBER 2022', 'Türkiye Beslenme Rehberi. Referans alım değerleri, porsiyon tanımları ve yaş/cinsiyet grubuna göre öneriler buradan gelir.'], ['USDA FoodData Central', 'Uluslararası bileşim kaynağı. Bir gıdanın aynı hazırlık hâliyle TürKomp karşılığı bulunmadığında başvurulur; kullanılan kayıt kimliği künyede görünür.']].map(([b, m]) => metinKart({ baslik: b, metin: m })).join(''))}${izgara(ikonKart({ href: 'sayfa/bilimsel-kaynaklar/', ikon: 'fa-flask', baslik: 'Bilimsel Kaynaklar ve Metodoloji', metin: 'Kaynakların sürümleri, künyenin dört alanı ve iki kaynağın neden aynı satırda karıştırılmadığı.' }) + ikonKart({ href: 'sayfa/editoryal-kurul/', ikon: 'fa-users', baslik: 'Editoryal ve Bilimsel Kurul', metin: 'İçeriğin hangi süreçten geçtiği, kimin sorumlu olduğu ve ticari iş birliklerinden bağımsızlık.' }), 'c2')}</div>`),
      bolum(`${bolumBas({ etiket: 'NE BULURSUN', ikon: 'fa-layer-group', baslik: 'Platformdaki Alanlar' })}${izgara(alanlar.map(([b, m, e, h]) => metinKart({ baslik: b, metin: m, eylem: linkDugme(e, h) })).join(''))}${bilgiNot()}`),
    ));
}

